      "dialogue": [
        {
          "speaker": "秘书",
          "zh": "这位是王教授，这位是马校长。",
          "py": "Zhè wèi shì Wáng jiàoshòu, zhè wèi shì Mǎ xiàozhǎng.",
          "vi": "Vị này là giáo sư Vương, vị này là hiệu trưởng Mã."
        },
        {
          "speaker": "王教授",
          "zh": "欢迎您，马校长！",
          "py": "Huānyíng nín, Mǎ xiàozhǎng!",
          "vi": "Nhiệt liệt hoan nghênh ngài, hiệu trưởng Mã!"
        },
        {
          "speaker": "田芳",
          "zh": "你也是语言学院的学生吗？",
          "py": "Nǐ yě shì Yǔyán Xuéyuàn de xuésheng ma?",
          "vi": "Bạn cũng là sinh viên học viện ngôn ngữ à?"
        },
        {
          "speaker": "罗兰",
          "zh": "是，我是留学生。我们都是留学生。",
          "py": "Shì, wǒ shì liúxuéshēng. Wǒmen dōu shì liúxuéshēng.",
          "vi": "Đúng vậy, tôi là du học sinh. Chúng tôi đều là du học sinh."
        }
      ],
      "grammar": [
        "Phó từ 都 (đều) và quy tắc: 都不是 (hoàn toàn không phải) vs 不都是 (không phải tất cả)",
        "Giới từ 跟 (cùng với): 跟谁一起",
        "Định ngữ nhiều tầng với 的: Định ngữ chỉ sở hữu/nơi chốn đứng trước định ngữ chỉ tính chất hoặc danh từ trung tâm (语言学院的学生 - sinh viên của Học viện Ngôn ngữ)."
      ]
