      "dialogue": [
        {
          "speaker": "田芳",
          "zh": "麦克，你今天什么时候来找我？",
          "py": "Màikè, nǐ jīntiān shénme shíhou lái zhǎo wǒ?",
          "vi": "Mike, hôm nay lúc nào cậu qua tìm tớ?",
          "section": "（一）我吃了早饭就来 (Tôi ăn sáng xong là qua ngay)"
        },
        {
          "speaker": "麦克",
          "zh": "我吃了早饭就来。你等我一会儿吧。",
          "py": "Wǒ chī le zǎofàn jiù lái. Nǐ děng wǒ yíhuìr ba.",
          "vi": "Tớ ăn sáng xong là qua ngay. Cậu đợi tớ một lát nhé.",
          "section": "（一）我吃了早饭就来 (Tôi ăn sáng xong là qua ngay)"
        },
        {
          "speaker": "田芳",
          "zh": "好的，来了以后咱们一起去租房子。",
          "py": "Hǎo de, lái le yǐhòu zánmen yìqǐ qù zū fángzi.",
          "vi": "Được rồi, cậu qua rồi chúng mình cùng nhau đi tìm thuê nhà nhé.",
          "section": "（一）我吃了早饭就来 (Tôi ăn sáng xong là qua ngay)"
        },
        {
          "speaker": "房东",
          "zh": "你看这套房子怎么样？有卧室、客厅、厨房和卫生间，还有个大阳台。",
          "py": "Nǐ kàn zhè tào fángzi zěnmeyàng? Yǒu wòshì, kètīng, chúfáng hé wèishēngjiān, hái yǒu ge dà yángtái.",
          "vi": "Các bạn xem căn hộ này thế nào? Có phòng ngủ, phòng khách, phòng bếp và nhà vệ sinh, lại còn có ban công lớn nữa.",
          "section": "（二）租房子 (Thuê nhà)"
        },
        {
          "speaker": "麦克",
          "zh": "环境很安静，交通也方便，离学校不太远。一个月房租多少钱？",
          "py": "Huánjìng hěn ānjìng, jiāotōng yě fāngbiàn, lí xuéxiào bú tài yuǎn. Yí ge yuè fángzū duōshao qián?",
          "vi": "Môi trường rất yên tĩnh, giao thông cũng thuận tiện, cách trường không xa lắm. Một tháng tiền thuê nhà là bao nhiêu ạ?",
          "section": "（二）租房子 (Thuê nhà)"
        },
        {
          "speaker": "房东",
          "zh": "两千五百块。要是你们满意，今天就可以签合同。",
          "py": "Liǎngqiān wǔbǎi kuài. Yàoshi nǐmen mǎnyì, jīntiān jiù kěyǐ qiān hétong.",
          "vi": "Hai nghìn năm trăm đồng. Nếu các bạn hài lòng thì hôm nay có thể ký hợp đồng luôn.",
          "section": "（二）租房子 (Thuê nhà)"
        },
        {
          "speaker": "麦克",
          "zh": "我们挺满意的，就租这套吧！",
          "py": "Wǒmen tǐng mǎnyì de, jiù zū zhè tào ba!",
          "vi": "Bọn cháu khá ưng ý, vậy thuê căn này đi ạ!",
          "section": "（二）租房子 (Thuê nhà)"
        }
      ],
      "grammar": [
        "Cấu trúc liên kết hai hành động liên tiếp: V1 + 了... 就 + V2... (Ăn sáng xong là đi ngay)",
        "Động từ xu hướng đơn: 来 / 去 (进/出/上/下/回/过/起 + 来/去)",
        "Cấu trúc liệt kê đặc điểm 又…又… (vừa… lại vừa…): Dùng để nối hai tính từ hoặc động từ cùng tính chất (这套房子又安静又方便)."
      ]
